    use foreclose_scrape::your_feature::{YourFeature, YourResult};

    #[test]
    fn test_creation() {
        let feature = YourFeature::new();
        // assertions
    }

    #[test]
    fn test_edge_case() {
        // edge case test
    }
}
```

### 5. **Key Conventions from Your Codebase**

- Use `tokio` for async operations
- Use `scraper` for HTML parsing
- Return `Result<T, Box<dyn Error>>` for error handling
- Keep modules focused and under 500 lines
- Follow TDD: write failing test first, then implement

